SET statement_timeout='5s';SELECT jsonb_build_object('publicGranted',(SELECT count(*) FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid IN ('entry_plan_authority_runs_v1'::regclass,'entry_plan_authority_jobs_v1'::regclass) AND a.grantee=0),'anonGranted',has_table_privilege('anon','entry_plan_authority_runs_v1','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_table_privilege('anon','entry_plan_authority_jobs_v1','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),'authenticatedGranted',has_table_privilege('authenticated','entry_plan_authority_runs_v1','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_table_privilege('authenticated','entry_plan_authority_jobs_v1','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'),'serviceBypass',(SELECT rolbypassrls FROM pg_roles WHERE rolname='service_role'));